// Code «Elegir los fuera de plazo» (06 · Recordatorios y vencimientos) · Run Once for All Items
// Recibe la salida de «Leer apartados activos» ({ total, apartados }) y devuelve un item por apartado
// con fecha_limite anterior a hoy, o un solo item { id: null, hoy, activos } si no hay ninguno.

const busqueda = $input.first().json;
if (!Array.isArray(busqueda.apartados)) {
  throw new Error('Elegir los fuera de plazo: «Leer apartados activos» no ha devuelto { total, apartados }');
}
const activos = busqueda.total ?? busqueda.apartados.length;

// Hoy en la zona de la tienda, AAAA-MM-DD (la app también usa Europe/Madrid)
const hoy = DateTime.now().setZone('Europe/Madrid').toISODate();

// Fuera de plazo: fecha_limite anterior a hoy. El que vence hoy todavía admite abonos (la app daría 422).
// Las fechas AAAA-MM-DD se comparan como texto. No se recalcula nada
const fuera = busqueda.apartados
  .filter(a => a.estado === 'activo' && String(a.fecha_limite) < hoy)
  .sort((a, b) => String(a.fecha_limite).localeCompare(String(b.fecha_limite)) || a.id - b.id);

const salida = fuera.map(a => ({ json: { ...a, hoy, activos } }));

// Un Code nunca devuelve 0 items: el IF «¿Hay apartados que vencer?» va por false
return salida.length ? salida : [{ json: { id: null, hoy, activos } }];

// Code «Preparar lista» (06 · Recordatorios y vencimientos) · Run Once for All Items
// Empareja cada apartado de «Elegir los fuera de plazo» con su respuesta de «Vencer apartado» y devuelve
// { asunto, texto } para «Enviar lista a la tienda». Un 404 o un 422 van a la lista; otro código para el flujo.

const elegidos = $('Elegir los fuera de plazo').all().filter(i => i.json.id != null);
const respuestas = $input.all();

// Las respuestas llegan en el mismo orden que los apartados (Batching de 1)
if (respuestas.length !== elegidos.length) {
  throw new Error(`Vencer apartado: se esperaban ${elegidos.length} respuestas y llegaron ${respuestas.length}`);
}

// Mensaje de la app: {"detail": "..."} o, si falla la validación, {"detail": [{msg: ...}]}
function detalle(body) {
  let b = body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { return b; } }
  const d = b?.detail;
  if (Array.isArray(d)) return d.map(x => x.msg ?? JSON.stringify(x)).join('; ');
  return d ?? JSON.stringify(b);
}

const vencidos = [];
const fallidos = [];
const otros = [];
elegidos.forEach((item, i) => {
  const elegido = item.json;
  const r = respuestas[i].json;
  if (r.statusCode === 200) {
    let b = r.body;
    if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
    // El apartado y el vale son los de la app; el importe del vale no se calcula
    vencidos.push({ apartado: b?.apartado ?? elegido, vale: b?.vale ?? null });
  } else if (r.statusCode === 404 || r.statusCode === 422) {
    fallidos.push({ apartado: elegido, motivo: detalle(r.body) });
  } else {
    otros.push({ apartado: elegido, statusCode: r.statusCode, motivo: detalle(r.body) });
  }
});

const vale = v => (v ? v.codigo : '(sin vale)');

// 401, 5xx…: para el flujo y lo avisa el 08. Con Never Error se intentan todos, así que el mensaje
// lleva los que sí se vencieron: la siguiente ejecución ya no los verá (están vencido)
if (otros.length) {
  const [primero] = otros;
  const resto = otros.length > 1 ? ` (y en ${otros.length - 1} más: ${otros.slice(1).map(o => o.apartado.id).join(', ')})` : '';
  const ya = vencidos.length ? vencidos.map(v => `${v.apartado.id} (${vale(v.vale)})`).join(', ') : 'ninguno';
  throw new Error(`Vencer apartado: la app respondió ${primero.statusCode} en el apartado ${primero.apartado.id}: ${primero.motivo}${resto}. Ya vencidos: ${ya}`);
}

// ---------- Texto de la lista ----------

const dia = iso => String(iso).split('-').reverse().join('/');
const e = n => `${Number(n).toFixed(2)} €`;
const zapato = a => `${a.producto}${a.talla ? `, talla ${a.talla}` : ''}`;
const seccion = (titulo, lineas) => `${titulo} (${lineas.length})\n${lineas.length ? lineas.join('\n') : '- Ninguno'}\n`;

const { hoy, activos } = elegidos[0].json;
const n = vencidos.length;

const texto = [
  `Vencimientos del ${dia(hoy)}: ${n} ${n === 1 ? 'apartado vencido' : 'apartados vencidos'} de ${activos} activos revisados.`,
  '',
  seccion('ZAPATOS QUE VUELVEN A LA VENTA', vencidos.map(({ apartado: a, vale: v }) =>
    `- ${zapato(a)} · apartado ${a.id} · ${a.cliente} · plazo hasta el ${dia(a.fecha_limite)} · vale ${vale(v)}${v ? ` de ${e(v.importe)}` : ''}`)),
  seccion('NO SE HAN PODIDO VENCER', fallidos.map(({ apartado: a, motivo }) =>
    `- ${zapato(a)} · apartado ${a.id} · ${a.cliente}. La app respondió: «${motivo}»`)),
  'Los vales los ha generado la app con lo abonado en cada apartado. Cada cliente recibe su vale por correo; si no tiene email, llega un aviso aparte para avisarle por teléfono.',
].join('\n');

const asunto = `Vencimientos del ${dia(hoy)}: ${n} ${n === 1 ? 'par vuelve' : 'pares vuelven'} a la venta`
  + (fallidos.length ? ` · ${fallidos.length} con error` : '');

return [{ json: { asunto, texto } }];
